// Equipment is brought from the bag, never left floating on a cabinet at entry.
export function stageInstrument176(bench,prepared){if(!bench)return;const visible=prepared.has('meter')&&(!bench.placement180||bench.placement180.placed||bench.placement180.active||bench.carry188?.held?.kind==='instrument'||bench.carry188?.instrumentPlaced);if(bench.instrument142)bench.instrument142.visible=visible;bench.group.traverse(o=>{if(/Cable_(red|black)|Cable_servicio143|sr129_(red|black)Probe|sr134_meterDisplay/.test(o.name))o.visible=visible;});for(const o of Object.values(bench.probes||{}))o.visible=visible;}
export function stageTrain176(view){const rig=view.rig;if(rig?.id!=='electrical'||!view.prepared176)return;const show=view.prepared176.has('meter');if(rig.parts.meter)rig.parts.meter.visible=show;for(const o of Object.values(rig.meterLeads123?.probes||{}))o.visible=show;for(const o of Object.values(rig.meterLeads123?.wires||{}))o.visible=show;}
